public class BankAccount{private final String owner;private double balance;public BankAccount(String o,double b){if(o==null||o.isBlank()||b<0)throw new IllegalArgumentException();owner=o;balance=b;}public void withdraw(double a)throws InsufficientFundsException{if(a<=0)throw new IllegalArgumentException();if(a>balance)throw new InsufficientFundsException(a-balance);balance-=a;}public double getBalance(){return balance;}public static void main(String[]a){var b=new BankAccount("Tadiwa",500);try{b.withdraw(650);}catch(InsufficientFundsException e){System.out.println(e.getMessage());}}}
